Contract ManageBookCopyCRUDService::addBookCopy(callNo:String,barcode:String,location:String): Boolean {
          definition:
          obsBook:Set(Book) = Book.allInstance()->select(b | b.CallNo = callNo), obsBarcode:Set(BookCopy) = BookCopy.allInstance()->select(o | o.Barcode = barcode)

            precondition:
          obsBook.isEmpty() = false and obsBarcode.isEmpty() = true

            postcondition:
          let newCopy:BookCopy in newCopy.oclIsNew() and BookCopy.allInstance()->includes(newCopy) and newCopy.Barcode = barcode and newCopy.Location = location and newCopy.Status = CopyStatus[AVAILABLE] and newCopy.BookBelongs = Book.allInstance()->any(b | b.CallNo = callNo)

        }
